import type { Row } from './shared';

export const OJT_ROADMAP_TARGET_SEMESTER=6;

// All priority and prerequisite claims are derived from the published curriculum, not generated by AI.
export function buildCoursePlan(input:{requirements:Row[];attempts:Row[];groups:Row[];aliases:Row[];catalog:Row[];valid:boolean}) {
  if(!input.valid)return {status:'DATA_INCOMPLETE',items:[],message:'Cần đối soát chương trình, tín chỉ và quy tắc tiên quyết trước khi gợi ý môn.'};
  if(input.requirements.some(r=>!Number.isInteger(r.recommendedSemester)||r.recommendedSemester<0))
    return {status:'DATA_INCOMPLETE',items:[],message:'Chưa xác định đầy đủ kỳ học của các môn trong chương trình. Cần nhà trường đối soát trước khi đề xuất lộ trình đến kỳ 6.'};
  // Scope both recommendations and dependency ranking to the OJT horizon.
  const requirements=input.requirements.filter(r=>r.recommendedSemester<=OJT_ROADMAP_TARGET_SEMESTER);
  const aliases=new Map<number,number>(input.aliases.map(a=>[a.SourceCourseID,a.TargetCourseID]));
  const canonical=(id:number)=>{const seen=new Set<number>();while(aliases.has(id)){if(seen.has(id))return -1;seen.add(id);id=aliases.get(id)!;}return id;};
  const passed=new Set<number>(input.attempts.filter(a=>['PASSED','RECOGNIZED'].includes(a.status)).map(a=>canonical(a.courseId)));
  const running=new Set<number>(input.attempts.filter(a=>a.status==='IN_PROGRESS').map(a=>canonical(a.courseId)));
  const failed=new Set<number>(input.attempts.filter(a=>a.status==='FAILED').map(a=>canonical(a.courseId)));
  const catalog=new Map<number,Row>(input.catalog.map(c=>[canonical(c.courseId),c]));
  const courses=new Map<number,Row>();
  for(const r of requirements)for(const choice of r.choices){const id=canonical(choice);if(id>0&&!r.completed&&!passed.has(id))courses.set(id,{...r,courseId:id});}
  const groupsFor=(id:number):Row[]=>input.groups.filter(g=>courses.get(id)?.id===g.requirementId)
    .map(g=>({...g,courseIds:[...new Set<number>(g.courseIds.map(canonical))]}));
  const count=(g:Row,extra?:number)=>g.courseIds.filter((id:number)=>passed.has(id)||id===extra).length;
  const describe=(id:number)=>({courseId:id,courseCode:catalog.get(id)?.courseCode??null,name:catalog.get(id)?.name??null});
  const items=[...courses].filter(([id])=>!running.has(id)).map(([id,r])=>{
    const prerequisites=groupsFor(id).map(g=>({minimumPassed:g.minimumPassed,passedCount:count(g),
      satisfied:count(g)>=g.minimumPassed,remainingRequired:Math.max(0,g.minimumPassed-count(g)),
      courses:g.courseIds.map((member:number)=>({...describe(member),passed:passed.has(member)}))}));
    const canPlan=prerequisites.every(g=>g.satisfied);
    const dependents=[...courses.keys()].filter(target=>target!==id&&!running.has(target)).flatMap(target=>{
      const groups=groupsFor(target);
      const relevant=groups.filter(g=>g.courseIds.includes(id)&&count(g)<g.minimumPassed);
      if(!relevant.length)return [];
      return [{...describe(target),unlocksAfterPassing:groups.every(g=>count(g,id)>=g.minimumPassed),
        mandatory:relevant.some(g=>g.minimumPassed===g.courseIds.length)}];
    });
    // Follow unmet dependency edges, de-duplicating descendants and preventing cycles.
    const descendants=new Set<number>();
    const visit=(node:number,path:Set<number>)=>{for(const target of courses.keys()){
      if(target===id||path.has(target))continue;
      if(!groupsFor(target).some(g=>g.courseIds.includes(node)&&count(g)<g.minimumPassed))continue;
      if(descendants.has(target))continue;descendants.add(target);visit(target,new Set([...path,target]));
    }};
    visit(id,new Set([id]));
    const action=failed.has(id)?'RETAKE':'STUDY';
    const names=dependents.map(d=>d.courseCode??`môn ID ${d.courseId}`).join(', ');
    let explanation=`${action==='RETAKE'?'Nên học lại':'Nên học'} ${describe(id).courseCode??r.courseCode??`môn ID ${id}`}`;
    explanation+=dependents.length?` vì môn này thuộc điều kiện tiên quyết chưa hoàn thành của ${names}.`:' để hoàn thành yêu cầu chương trình và tích lũy tín chỉ.';
    if(dependents.some(d=>!d.mandatory))explanation+=' Với nhóm tiên quyết lựa chọn, môn này là một phương án để đáp ứng nhóm, không nhất thiết là lựa chọn duy nhất.';
    if(!canPlan)explanation+=' Trước khi học môn này, cần hoàn thành các nhóm tiên quyết còn thiếu được liệt kê bên dưới.';
    return {...describe(id),requirementId:r.id,recommendedSemester:r.recommendedSemester,credits:r.credits,action,canPlan,
      isAlternative:r.choices.length>1,prerequisites,dependentCourses:dependents,
      directDependentCount:dependents.length,unlocksCount:dependents.filter(d=>d.unlocksAfterPassing).length,
      downstreamCount:descendants.size,downstreamCourses:[...descendants].map(describe),explanation,availability:'NOT_MANAGED'};
  });
  items.sort((a,b)=>Number(b.canPlan)-Number(a.canPlan)||b.unlocksCount-a.unlocksCount||b.downstreamCount-a.downstreamCount||
    b.directDependentCount-a.directDependentCount||Number(b.action==='RETAKE')-Number(a.action==='RETAKE')||a.courseId-b.courseId);
  return {status:'READY',items:items.map((r,i)=>({...r,priority:i+1})),
    message:'Chỉ đề xuất môn trong lộ trình đến kỳ thực tập 6; không bao gồm các môn kỳ 7–9. Ưu tiên môn có thể lên kế hoạch và mở điều kiện cho các môn trong phạm vi này. Đây không phải xác nhận mở lớp hoặc cho phép đăng ký. Môn trong cùng lựa chọn không được cộng tín chỉ nhiều lần.'};
}
